<body>
    <div class="monitor-container">
        <div class="monitor-header">
            <div class="monitor-title">
                <div class="rec-indicator"></div>
                <span>监控系统</span>
                <span class="hd-badge">HD</span>
            </div>
            <div class="monitor-info">
                <span>CAM 01</span>
                <span id="current-datetime"></span>
            </div>
        </div>

        <div class="monitor-screen">
            <div class="grid-overlay"></div>
            <div class="monitor-content" id="monitorContent">$1</div>
        </div>

        <div class="monitor-footer">
            <div class="status-indicators">
                <div class="status-item">
                    <div class="status-light"></div>
                    <span>在线</span>
                </div>
                <div class="status-item">
                    <div class="status-light"></div>
                    <span>录制中</span>
                </div>
                <div class="status-item">
                    <div class="status-light" style="background: #007aff;"></div>
                    <span>1080P</span>
                </div>
            </div>
            <div class="control-buttons">
                <button class="control-btn" onclick="clearMonitor()">清除记录</button>
            </div>
        </div>
    </div>

    <script>
        // 更新时间
        function updateTime() {
            const now = new Date();
            const dateTimeStr = now.toLocaleString('zh-CN', { 
                year: 'numeric', 
                month: '2-digit', 
                day: '2-digit',
                hour: '2-digit',
                minute: '2-digit',
                second: '2-digit',
                hour12: false
            });

            document.getElementById('current-datetime').textContent = dateTimeStr;
        }

        // 清除监控记录
        function clearMonitor() {
            const container = document.getElementById('monitorContent');
            const timestamp = new Date().toLocaleTimeString('zh-CN', { 
                hour: '2-digit',
                minute: '2-digit',
                second: '2-digit',
                hour12: false
            });
            container.innerHTML = `<span class="timestamp">[${timestamp}]</span><span style="color: #ffa500;">系统提示：监控记录已清除</span>`;

            setTimeout(() => {
                container.innerHTML = '';
            }, 3000);
        }

        // 处理内容显示
        function processContent() {
            const content = document.getElementById('monitorContent').innerText;
            if (content && content !== '$1') {
                const lines = content.split('\n');
                const processedLines = lines.map(line => {
                    if (line.trim()) {
                        const timestamp = new Date().toLocaleTimeString('zh-CN', { 
                            hour: '2-digit',
                            minute: '2-digit',
                            second: '2-digit',
                            hour12: false
                        });
                        return `<span class="timestamp">[${timestamp}]</span>${line}`;
                    }
                    return line;
                });
                document.getElementById('monitorContent').innerHTML = processedLines.join('\n');
            }
        }

        // 初始化
        updateTime();
        setInterval(updateTime, 1000);

        // 延迟处理内容，确保DOM加载完成
        setTimeout(processContent, 100);
    </script>
</body>
</html>
