        /* 遮罩层 */
        .overlay {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: rgba(0,0,0,0.4);
            z-index: 1050;
            display: none;
        }

        .overlay.show {
            display: block;
        }

        /* 通知样式 */
        .notification {
