        .sms-send:disabled {
            opacity: 0.5;
        }

        /* 地图应用 */
        .map-container {
            flex: 1;
            overflow-y: auto;
            background: #f5efdc;
            padding: 20px;
            -webkit-overflow-scrolling: touch;
        }

        .map-title {
            text-align: center;
            color: #4E342E;
            font-size: clamp(20px, 5vw, 24px);
            margin-bottom: 20px;
            font-weight: bold;
        }

        .map-section {
            margin-bottom: 20px;
        }

        .map-section-title {
            color: #5C4033;
            font-size: clamp(14px, 3.5vw, 18px);
            font-weight: 600;
            margin-bottom: 10px;
            padding-bottom: 5px;
