                    <div class="app-grid">
                        <div class="app-icon" data-app="sms">
                            <div class="app-icon-img" style="background: rgba(76,217,100,0.95);">💬</div>
                            <div class="app-icon-label">信息</div>
                        </div>
                        <div class="app-icon" data-app="map">
