                            <div class="app-icon-label">地图</div>
                        </div>
                        <div class="app-icon" data-app="forum">
                            <div class="app-icon-img" style="background: rgba(255,69,58,0.95);">📝</div>
                            <div class="app-icon-label">论坛</div>
                        </div>
                        <div class="app-icon" data-app="monitor">
                            <div class="app-icon-img" style="background: rgba(0,30,0,0.95);">👁️</div>
                            <div class="app-icon-label">监控模式</div>
                        </div>
                        <div class="app-icon" data-app="camera">
