                                    码头市场
                                </button>
                                <button class="location-button" onclick="showAreaDetails('大浴场')">
                                    大浴场
                                </button>
                            </div>
                        </div>

                        <div class="map-section">
                            <div class="map-section-title">🏛️ 镇中心</div>
                            <div class="location-grid">
                                <button class="location-button" onclick="confirmNavigation('汐海镇广场')">
                                    汐海镇广场
                                </button>
                                <button class="location-button" onclick="confirmNavigation('商业街')">
                                    商业街
                                </button>
