    <script>
        // 状态变量
        let currentMapView = 'main';
        let currentAreaDetails = '';
        let pendingAction = '';
        let pendingParam = '';

        // 时间更新
        function updateTime() {
            const now = new Date();
            const hours = String(now.getHours()).padStart(2, '0');
            const minutes = String(now.getMinutes()).padStart(2, '0');
            const timeString = `${hours}:${minutes}`;

            document.getElementById('status-time').textContent = timeString;
            document.getElementById('lock-time').textContent = timeString;

            const days = ['星期日', '星期一', '星期二', '星期三', '星期四', '星期五', '星期六'];
            const dateString = `${now.getMonth() + 1}月${now.getDate()}日 ${days[now.getDay()]}`;
            document.getElementById('lock-date').textContent = dateString;
        }

        updateTime();
        setInterval(updateTime, 1000);

        // 解锁功能
        const lockScreen = document.getElementById('lock-screen');
        lockScreen.addEventListener('click', () => {
            lockScreen.classList.add('unlocked');
        });

        // 应用管理
        document.querySelectorAll('.app-icon').forEach(app => {
            app.addEventListener('click', () => {
                const appName = app.dataset.app;
                const appScreen = document.getElementById(`${appName}-app`);
                if (appScreen) {
                    appScreen.classList.add('active');

                    // 如果是论坛应用，显示打开论坛的通知
                    if (appName === 'forum') {
                        showNotification('汐海论坛已打开');
                        sendCommand('（打开论坛）');
                    }
                    // 如果是监控模式，自动发送命令
                    if (appName === 'monitor') {
                        showNotification('监控系统已启动');
                        sendCommand('（打开监控模式）');
                    }
                } else {
                    showNotification(`${app.querySelector('.app-icon-label').textContent}应用暂未开放`);
                }
            });
        });

        function closeApp(appId) {
            document.getElementById(appId).classList.remove('active');

            // 如果关闭的是地图应用，重置地图状态
            if (appId === 'map-app') {
                resetMapView();
            }
        }

        // 切换论坛标签
        function switchForumTab(tabElement, tabName) {
            // 移除所有标签的active类
            document.querySelectorAll('.forum-tab').forEach(tab => {
                tab.classList.remove('active');
            });

            // 为当前标签添加active类
            tabElement.classList.add('active');

            // 这里可以添加根据标签切换内容的逻辑
            showNotification(`切换到${tabElement.textContent}标签`);
        }

        // 论坛帖子打开确认
        function confirmOpenForum(title) {
            pendingAction = 'openForum';
            pendingParam = title;
            document.getElementById('confirm-title').textContent = '打开帖子';
            document.getElementById('confirm-message').textContent = `确定要打开"${title}"吗？`;
            document.getElementById('overlay').classList.add('show');
            document.getElementById('confirm-dialog').classList.add('show');

            // 设置确认按钮的点击事件
            document.getElementById('confirm-ok').onclick = function() {
                openForumPost(pendingParam);
            };
        }

        // 打开论坛帖子
        function openForumPost(title) {
            if (sendCommand(`（浏览论坛帖子：${title}）`)) {
                showNotification(`正在打开: ${title}`);
                cancelDialog(); // 关闭确认对话框
                setTimeout(() => {
                    closeApp('forum-app');
                }, 1000);
            } else {
                showNotification('打开帖子失败');
                cancelDialog();
            }
        }

        // 监控系统功能
        function startMonitoring() {
            const logs = document.getElementById('monitor-logs');
            const now = new Date();
            const timeString = `[${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}:${String(now.getSeconds()).padStart(2, '0')}]`;

            const logEntry = document.createElement('div');
            logEntry.className = 'log-entry';
            logEntry.innerHTML = `<span class="log-time">${timeString}</span><span class="log-alert">启动全面监控模式</span>`;
            logs.appendChild(logEntry);
            logs.scrollTop = logs.scrollHeight;

            sendCommand('（启动全面监控模式）');
            showNotification('全面监控模式已激活');

            // 添加随机监控日志
            setInterval(() => {
                const randomMessages = [
                    "主卧检测到活动",
                    "一楼浴室门锁故障，门已打开",
                    "检测到门外有人",
                    "系统存储空间更新",
                    "客厅监控正常",
                    "备份完成",
                    "系统进行例行检查"
                ];

                const now = new Date();
                const timeString = `[${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}:${String(now.getSeconds()).padStart(2, '0')}]`;

                const message = randomMessages[Math.floor(Math.random() * randomMessages.length)];
                const isAlert = message.includes("门锁故障") || message.includes("检测到");

                const logEntry = document.createElement('div');
                logEntry.className = 'log-entry';
                logEntry.innerHTML = `<span class="log-time">${timeString}</span><span class="${isAlert ? 'log-alert' : 'log-message'}">${message}</span>`;
                logs.appendChild(logEntry);

                // 保持最多显示20条日志
                while (logs.children.length > 20) {
                    logs.removeChild(logs.children[0]);
                }

                logs.scrollTop = logs.scrollHeight;
            }, 5000);
        }

        // 地图视图管理
        function showAreaDetails(areaId) {
            // 隐藏主地图视图
            document.getElementById('main-map-view').style.display = 'none';

            // 隐藏所有区域详情
            document.querySelectorAll('.area-details').forEach(el => {
                el.classList.remove('active');
            });

            // 显示选中的区域详情
            document.getElementById(`area-details-${areaId}`).classList.add('active');

            // 更新返回按钮功能和标题
            document.getElementById('map-back-button').onclick = resetMapView;
            document.getElementById('map-title').textContent = areaId;

            currentMapView = 'details';
            currentAreaDetails = areaId;
        }

        function resetMapView() {
            // 显示主地图视图
            document.getElementById('main-map-view').style.display = 'block';

            // 隐藏所有区域详情
            document.querySelectorAll('.area-details').forEach(el => {
                el.classList.remove('active');
            });

            // 重置返回按钮功能和标题
            document.getElementById('map-back-button').onclick = function() { closeApp('map-app'); };
            document.getElementById('map-title').textContent = '汐海镇地图';

            currentMapView = 'main';
            currentAreaDetails = '';
        }

        // 发送命令
        function sendCommand(message) {
            try {
                if (typeof triggerSlash === 'function') {
                    triggerSlash(`/send ${message}|/trigger`);
                    return true;
                }

                const methods = [
                    () => window.triggerSlash?.(`/send ${message}|/trigger`),
                    () => window.parent?.triggerSlash?.(`/send ${message}|/trigger`),
                    () => window.top?.triggerSlash?.(`/send ${message}|/trigger`),
                    () => window.parent?.postMessage({
                        type: 'stt-command',
                        command: `/send ${message}|/trigger`
                    }, '*')
                ];

                for (let method of methods) {
                    try {
                        method();
                        return true;
                    } catch (e) {}
                }

                return false;
            } catch (e) {
                console.error('发送命令失败:', e);
                return false;
            }
        }

        // 通知功能
        function showNotification(message) {
            const notification = document.getElementById('notification');
            notification.textContent = message;
            notification.classList.add('show');

            setTimeout(() => {
                notification.classList.remove('show');
            }, 3000);
        }

        // 短信功能
        const smsInput = document.getElementById('sms-input');
        const smsSend = document.getElementById('sms-send');

        smsInput.addEventListener('input', function() {
            smsSend.disabled = !this.value.trim();
            this.style.height = 'auto';
            this.style.height = Math.min(this.scrollHeight, 100) + 'px';
        });

        function sendSMS() {
            const message = smsInput.value.trim();

            if (message) {
                const messageDiv = document.createElement('div');
                messageDiv.className = 'message sent';
                messageDiv.textContent = message;
                document.getElementById('sms-messages').appendChild(messageDiv);

                if (sendCommand(`（发送短信给林素萱）${message}`)) {
                    showNotification('短信已发送');
                } else {
                    showNotification('发送失败');
                }

                smsInput.value = '';
                smsInput.style.height = 'auto';
                smsSend.disabled = true;

                const messagesContainer = document.getElementById('sms-messages');
                messagesContainer.scrollTop = messagesContainer.scrollHeight;
            }
        }

        smsInput.addEventListener('keypress', (e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                sendSMS();
            }
        });

        // 导航功能
        function confirmNavigation(location) {
            pendingAction = 'navigate';
            pendingParam = location;
            document.getElementById('confirm-title').textContent = '确认前往';
            document.getElementById('confirm-message').textContent = `确定要前往 ${location} 吗？`;
            document.getElementById('overlay').classList.add('show');
            document.getElementById('confirm-dialog').classList.add('show');

            // 设置确认按钮的点击事件
            document.getElementById('confirm-ok').onclick = function() {
                navigateTo(pendingParam);
            };
        }

        function cancelDialog() {
            document.getElementById('overlay').classList.remove('show');
            document.getElementById('confirm-dialog').classList.remove('show');
            pendingAction = '';
            pendingParam = '';
        }

        // 取消导航确认
        function cancelNavigation() {
            cancelDialog();
        }

        function navigateTo(location) {
            if (sendCommand(`前往 ${location}`)) {
                showNotification(`正在前往: ${location}`);
                cancelDialog(); // 关闭确认对话框
                setTimeout(() => {
                    closeApp('map-app');
                }, 1000);
            } else {
                showNotification('导航失败');
                cancelDialog();
            }
        }

        // 防止双击缩放
        let lastTouchEnd = 0;
        document.addEventListener('touchend', function(event) {
            const now = Date.now();
            if (now - lastTouchEnd <= 300) {
                event.preventDefault();
            }
            lastTouchEnd = now;
        }, false);

        // 防止捏合缩放
        document.addEventListener('touchstart', function(event) {
            if (event.touches.length > 1) {
                event.preventDefault();
            }
        }, { passive: false });

        console.log('魔法手机界面加载完成');
    </script>
</body>
</html>
